'section'\"\n    :class=\"['members-panel', 'iz-panel', 'iz-panel--list', { 'iz-panel--flush': embedded }]\"\n  >\n    <div\n      v-if=\"!embedded\"\n      class=\"members-panel__header\"\n      @click=\"collapsed = !collapsed\"\n    >\n      <h3 class=\"members-panel__title iz-panel__title\">\n        <svg\n          xmlns=\"http://www.w3.org/2000/svg\"\n          width=\"18\"\n          height=\"18\"\n          viewBox=\"0 0 24 24\"\n          fill=\"none\"\n          stroke=\"currentColor\"\n          stroke-width=\"2\"\n          stroke-linecap=\"round\"\n          stroke-linejoin=\"round\"\n        >\n          <path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\" />\n          <circle cx=\"9\" cy=\"7\" r=\"4\" />\n          <path d=\"M23 21v-2a4 4 0 0 0-3-3.87\" />\n          <path d=\"M16 3.13a4 4 0 0 1 0 7.75\" />\n        </svg>\n        Team Members\n        <span class=\"members-panel__count\">{{ members.length }}</span>\n      </h3>\n      <svg\n        xmlns=\"http://www.w3.org/2000/svg\"\n        width=\"18\"\n        height=\"18\"\n        viewBox=\"0 0 24 24\"\n        fill=\"none\"\n        stroke=\"currentColor\"\n        stroke-width=\"2\"\n        stroke-linecap=\"round\"\n        stroke-linejoin=\"round\"\n        class=\"members-panel__chevron\"\n        :class=\"{ 'members-panel__chevron--rotated': collapsed }\"\n      >\n        <polyline points=\"18 15 12 9 6 15\" />\n      </svg>\n    </div>\n\n    <div v-show=\"embedded || !collapsed\" class=\"members-panel__body\">\n      <div v-if=\"toast\" class=\"members-panel__toast\">\n        <span aria-hidden=\"true\">✓</span>\n        <span>{{ toast.message }}</span>\n      </div>\n\n      <!-- Filters -->\n      <div class=\"members-panel__filters\">\n        <input\n          v-model=\"search\"\n          class=\"members-panel__search iz-input iz-input--sm\"\n          type=\"text\"\n          placeholder=\"Search members…\"\n        />\n        <div class=\"members-panel__role-badges\">\n          <span\n            class=\"iz-chip\"\n            :class=\"{ 'iz-chip--active': roleFilter === '' }\"\n            @click=\"\n              roleFilter = '';\n              currentPage = 1;\n            \"\n            >All</span\n          >\n          <span\n            class=\"iz-chip iz-chip--accent\"\n            :class=\"{\n              'members-panel__role-badge--active': roleFilter === 'admin',\n            }\"\n            @click=\"\n              roleFilter = 'admin';\n              currentPage = 1;\n            \"\n            >Admin</span\n          >\n          <span\n            class=\"iz-chip iz-chip--muted\"\n            :class=\"{\n              'members-panel__role-badge--active': roleFilter === 'member',\n            }\"\n            @click=\"\n              roleFilter = 'member';\n              currentPage = 1;\n            \"\n            >Member</span\n          >\n        </div>\n        <button\n          type=\"button\"\n          class=\"members-panel__add-toggle\"\n          @click=\"openAddMode\"\n        >+ Add member</button>\n      </div>\n\n      <div v-if=\"addMode\" class=\"iz-user-picker members-panel__add-form\">\n        <div class=\"members-panel__add-form-header\">\n          <span class=\"members-panel__add-form-title\">Add member</span>\n          <button\n            type=\"button\"\n            class=\"iz-close iz-close--sm\"\n            @click=\"closeAddMode\"\n            aria-label=\"Close add form\"\n          >×</button>\n        </div>\n\n        <!-- Credentials reveal card (auto-generated success) -->\n        <div v-if=\"createdUser\" class=\"iz-reveal members-panel__reveal\">\n          <div class=\"iz-reveal__heading\">\n            <span class=\"iz-reveal__check\" aria-hidden=\"true\">✓</span>\n            User created and added\n          </div>\n          <div class=\"iz-reveal__row\">\n            <span class=\"iz-reveal__label\">UID</span>\n            <span class=\"iz-reveal__value\">{{ createdUser.uid }}</span>\n            <button\n              type=\"button\"\n              class=\"iz-btn iz-btn--sm\"\n              @click=\"copyToClipboard(createdUser.uid, 'uid')\"\n            >{{ copyFlags.uid ? \"Copied!\" : \"Copy\" }}</button>\n          </div>\n          <div class=\"iz-reveal__row\">\n            <span class=\"iz-reveal__label\">Password</span>\n            <span class=\"iz-reveal__value\">\n              <template v-if=\"revealCreatedPassword\">{{ createdUser.password }}</template>\n              <template v-else>{{ \"•\".repeat(createdUser.password.length) }}</template>\n            </span>\n            <button\n              type=\"button\"\n              class=\"iz-btn iz-btn--sm\"\n              @click=\"revealCreatedPassword = !revealCreatedPassword\"\n            >{{ revealCreatedPassword ? \"Hide\" : \"Show\" }}</button>\n            <button\n              type=\"button\"\n              class=\"iz-btn iz-btn--sm\"\n              @click=\"copyToClipboard(createdUser.password, 'password')\"\n            >{{ copyFlags.password ? \"Copied!\" : \"Copy\" }}</button>\n          </div>\n          <div class=\"iz-reveal__row iz-reveal__row--actions\">\n            <button\n              type=\"button\"\n              class=\"iz-btn iz-btn--sm\"\n              @click=\"copyToClipboard(createdUser.uid + ' / ' + createdUser.password, 'both')\"\n            >{{ copyFlags.both ? \"Copied!\" : \"Copy both\" }}</button>\n          </div>\n          <p class=\"iz-reveal__warning\">\n            Share these credentials with the user now — the password won't be visible again.\n          </p>\n          <div class=\"iz-reveal__row iz-reveal__row--actions\">\n            <button\n              type=\"button\"\n              class=\"iz-btn iz-btn--primary\"\n              @click=\"confirmCreatedUser\"\n            >Done</button>\n          </div>\n        </div>\n\n        <!-- Tabbed add UI (hidden while reveal card is showing) -->\n        <template v-else>\n          <div class=\"members-panel__add-tabs\" role=\"tablist\">\n            <button\n              type=\"button\"\n              role=\"tab\"\n              class=\"members-panel__add-tab\"\n              :class=\"{ 'members-panel__add-tab--active': addTab === 'existing' }\"\n              :aria-selected=\"addTab === 'existing'\"\n              @click=\"addTab = 'existing'\"\n            >Existing user</button>\n            <button\n              type=\"button\"\n              role=\"tab\"\n              class=\"members-panel__add-tab\"\n              :class=\"{ 'members-panel__add-tab--active': addTab === 'new' }\"\n              :aria-selected=\"addTab === 'new'\"\n              @click=\"addTab = 'new'\"\n            >New user</button>\n          </div>\n\n          <!-- Existing user tab -->\n          <div v-if=\"addTab === 'existing'\">\n            <input\n              type=\"search\"\n              class=\"iz-input\"\n              :value=\"addSearchTerm\"\n              @input=\"onAddSearchInput($event)\"\n              placeholder=\"Search by name, email, or UID (min 2 characters)…\"\n            />\n            <div v-if=\"addError\" class=\"iz-error members-panel__add-form-error\">\n              {{ addError }}\n            </div>\n            <div v-if=\"addSearchLoading\" class=\"iz-state\">\n              Searching…\n            </div>\n            <div\n              v-else-if=\"addSearchTerm.trim().length >= 2 && addSearchResults.length === 0\"\n              class=\"iz-state\"\n            >\n              No users match.\n            </div>\n            <ul\n              v-else-if=\"addSearchResults.length > 0\"\n              class=\"iz-user-picker__results\"\n            >\n              <li\n                v-for=\"u in addSearchResults\"\n                :key=\"'avail-' + u.uid\"\n                class=\"iz-user-picker__result\"\n              >\n                <div class=\"iz-identity__body\">\n                  <span class=\"iz-identity__name\">\n                    {{ u.displayName || u.uid }}\n                  </span>\n                  <span class=\"iz-identity__meta\">\n                    <template v-if=\"u.email\">{{ u.email }} · </template>uid: {{ u.uid }}\n                  </span>\n                </div>\n                <button\n                  type=\"button\"\n                  class=\"iz-user-picker__add\"\n                  :disabled=\"addingUid !== null\"\n                  :aria-label=\"'Add ' + (u.displayName || u.uid)\"\n                  @click=\"addMember(u.uid)\"\n                >\n                  <span\n                    v-if=\"addingUid === u.uid\"\n                    class=\"iz-spinner iz-spinner--sm\"\n                    aria-hidden=\"true\"\n                  ></span>\n                  <span v-else aria-hidden=\"true\">+</span>\n                </button>\n              </li>\n            </ul>\n          </div>\n\n          <!-- New user tab -->\n          <div v-else-if=\"addTab === 'new'\">\n            <div class=\"members-panel__field\">\n              <label class=\"members-panel__field-label\" for=\"newuser-uid\">\n                UID <span class=\"members-panel__field-required\">*</span>\n              </label>\n              <input\n                id=\"newuser-uid\"\n                type=\"text\"\n                class=\"iz-input\"\n                v-model=\"newUser.uid\"\n                autocomplete=\"off\"\n                spellcheck=\"false\"\n                :disabled=\"newUserSubmitting\"\n                @blur=\"markBlurred('uid')\"\n              />\n              <div\n                v-if=\"newUserBlurred.uid && newUserFieldErrors.uid\"\n                class=\"members-panel__field-error\"\n              >{{ newUserFieldErrors.uid }}</div>\n            </div>\n\n            <div class=\"members-panel__field\">\n              <label class=\"members-panel__field-label\" for=\"newuser-display\">\n                Display name <span class=\"members-panel__field-required\">*</span>\n              </label>\n              <input\n                id=\"newuser-display\"\n                type=\"text\"\n                class=\"iz-input\"\n                v-model=\"newUser.displayName\"\n                :disabled=\"newUserSubmitting\"\n                @blur=\"markBlurred('displayName')\"\n              />\n              <div\n                v-if=\"newUserBlurred.displayName && newUserFieldErrors.displayName\"\n                class=\"members-panel__field-error\"\n              >{{ newUserFieldErrors.displayName }}</div>\n            </div>\n\n            <div class=\"members-panel__field\">\n              <label class=\"members-panel__field-label\" for=\"newuser-email\">Email</label>\n              <input\n                id=\"newuser-email\"\n                type=\"email\"\n                class=\"iz-input\"\n                v-model=\"newUser.email\"\n                autocomplete=\"off\"\n                :disabled=\"newUserSubmitting\"\n                @blur=\"markBlurred('email')\"\n              />\n              <div\n                v-if=\"newUserBlurred.email && newUserFieldErrors.email\"\n                class=\"members-panel__field-error\"\n              >{{ newUserFieldErrors.email }}</div>\n            </div>\n\n            <div class=\"members-panel__field\">\n              <label class=\"members-panel__field-label\" for=\"newuser-password\">\n                Password <span class=\"members-panel__field-required\">*</span>\n              </label>\n              <div class=\"members-panel__password-row\">\n                <input\n                  id=\"newuser-password\"\n                  :type=\"newUserShowPassword ? 'text' : 'password'\"\n                  class=\"members-panel__add-form-input members-panel__password-input\"\n                  v-model=\"newUser.password\"\n                  :readonly=\"newUser.autoGenerate\"\n                  :disabled=\"newUserSubmitting\"\n                  autocomplete=\"new-password\"\n                  @blur=\"markBlurred('password')\"\n                />\n                <button\n                  type=\"button\"\n                  class=\"iz-btn iz-btn--icon members-panel__icon-btn\"\n                  :aria-label=\"newUserShowPassword ? 'Hide password' : 'Show password'\"\n                  :title=\"newUserShowPassword ? 'Hide password' : 'Show password'\"\n                  :disabled=\"newUserSubmitting\"\n                  @click=\"newUserShowPassword = !newUserShowPassword\"\n                >\n                  <svg\n                    v-if=\"newUserShowPassword\"\n                    xmlns=\"http://www.w3.org/2000/svg\"\n                    width=\"20\"\n                    height=\"20\"\n                    viewBox=\"0 0 24 24\"\n                    fill=\"none\"\n                    stroke=\"currentColor\"\n                    stroke-width=\"2\"\n                    stroke-linecap=\"round\"\n                    stroke-linejoin=\"round\"\n                    aria-hidden=\"true\"\n                  >\n                    <path d=\"M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94\" />\n                    <path d=\"M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19\" />\n                    <path d=\"M14.12 14.12a3 3 0 1 1-4.24-4.24\" />\n                    <line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\" />\n                  </svg>\n                  <svg\n                    v-else\n                    xmlns=\"http://www.w3.org/2000/svg\"\n                    width=\"20\"\n                    height=\"20\"\n                    viewBox=\"0 0 24 24\"\n                    fill=\"none\"\n                    stroke=\"currentColor\"\n                    stroke-width=\"2\"\n                    stroke-linecap=\"round\"\n                    stroke-linejoin=\"round\"\n                    aria-hidden=\"true\"\n                  >\n                    <path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\" />\n                    <circle cx=\"12\" cy=\"12\" r=\"3\" />\n                  </svg>\n                </button>\n                <button\n                  v-if=\"newUser.autoGenerate\"\n                  type=\"button\"\n                  class=\"iz-btn iz-btn--icon members-panel__icon-btn\"\n                  aria-label=\"Regenerate password\"\n                  title=\"Regenerate password\"\n                  :disabled=\"newUserSubmitting\"\n                  @click=\"newUser.password = generatePassword()\"\n                >↻</button>\n              </div>\n              <label class=\"members-panel__autogen\">\n                <input\n                  type=\"checkbox\"\n                  v-model=\"newUser.autoGenerate\"\n                  :disabled=\"newUserSubmitting\"\n                  @change=\"onAutoGenerateChange\"\n                />\n                Auto-generate\n              </label>\n              <div\n                v-if=\"newUserBlurred.password && newUserFieldErrors.password\"\n                class=\"members-panel__field-error\"\n              >{{ newUserFieldErrors.password }}</div>\n            </div>\n\n            <div\n              v-if=\"newUserError\"\n              class=\"iz-error members-panel__add-form-error\"\n            >{{ newUserError }}</div>\n\n            <div class=\"members-panel__form-actions\">\n              <button\n                type=\"button\"\n                class=\"iz-btn iz-btn--ghost\"\n                :disabled=\"newUserSubmitting\"\n                @click=\"closeAddMode\"\n              >Cancel</button>\n              <button\n                type=\"button\"\n                class=\"iz-btn iz-btn--primary\"\n                :disabled=\"newUserSubmitting || !newUserFormValid\"\n                @click=\"submitNewUser\"\n              >\n                <span\n                  v-if=\"newUserSubmitting\"\n                  class=\"iz-spinner iz-spinner--sm\"\n                  aria-hidden=\"true\"\n                ></span>\n                Create &amp; add member\n              </button>\n            </div>\n          </div>\n        </template>\n      </div>\n\n      <div v-if=\"filteredMembers.length === 0\" class=\"members-panel__empty\">\n        No members match your filters.\n      </div>\n\n      <div\n        v-for=\"member in paginatedMembers\"\n        :key=\"'mem-' + member.userId\"\n        class=\"members-panel__card iz-row--card iz-row--expandable\"\n        :class=\"{ 'iz-row--expanded': expanded[member.userId] }\"\n      >\n        <!-- Summary Row (always visible, clickable) -->\n        <div class=\"members-panel__row iz-row__header\" @click=\"toggle(member.userId)\">\n          <span class=\"iz-identity__avatar\">{{\n            (member.displayName || member.userId).charAt(0).toUpperCase()\n          }}</span>\n          <div class=\"iz-identity__body members-panel__info\">\n            <span class=\"iz-identity__name members-panel__name\">{{\n              member.displayName || member.userId\n            }}</span>\n            <span\n              class=\"iz-identity__meta members-panel__sub\"\n              v-if=\"member.title || member.email\"\n            >\n              {{ member.title ? member.title : member.email }}\n            </span>\n          </div>\n          <div\n            v-if=\"confirmRemoveUid === member.userId\"\n            class=\"iz-row__actions members-panel__right--confirm\"\n            @click.stop\n          >\n            <span class=\"members-panel__confirm-text\">Remove?</span>\n            <span\n              v-if=\"removeError\"\n              class=\"members-panel__confirm-error\"\n            >{{ removeError }}</span>\n            <button\n              type=\"button\"\n              class=\"members-panel__confirm-btn members-panel__confirm-btn--danger\"\n              :disabled=\"removingUid === member.userId\"\n              @click.stop=\"confirmRemove(member.userId)\"\n            >\n              <span\n                v-if=\"removingUid === member.userId\"\n                class=\"iz-spinner iz-spinner--sm\"\n                aria-hidden=\"true\"\n              ></span>\n              Confirm\n            </button>\n            <button\n              type=\"button\"\n              class=\"members-panel__confirm-btn\"\n              :disabled=\"removingUid === member.userId\"\n              @click.stop=\"cancelRemove()\"\n            >Cancel</button>\n          </div>\n          <div v-else class=\"iz-row__actions\">\n            <span\n              v-if=\"member.assignedTasks > 0\"\n              class=\"iz-pill iz-pill--accent members-panel__stat-pill\"\n            >\n              {{ member.doneTasks }}/{{ member.assignedTasks }}\n              <span class=\"members-panel__stat-label\">tasks</span>\n            </span>\n            <span\n              v-if=\"member.overdueTasks > 0\"\n              class=\"iz-pill iz-pill--danger members-panel__stat-pill\"\n            >\n              {{ member.overdueTasks }}\n              <span class=\"members-panel__stat-label\">overdue</span>\n            </span>\n            <span\n              v-if=\"isOwner(member)\"\n              class=\"members-panel__role members-panel__role--owner\"\n              title=\"Organization owner\"\n            >Owner</span>\n            <span\n              class=\"members-panel__role\"\n              :class=\"'members-panel__role--' + member.role\"\n            >\n              {{ member.role }}\n            </span>\n            <button\n              type=\"button\"\n              class=\"members-panel__remove-btn\"\n              :disabled=\"isOwner(member)\"\n              :title=\"isOwner(member) ? 'Organization owner — handover required to remove' : 'Remove member'\"\n              @click.stop=\"requestRemove(member.userId)\"\n            >\n              <svg\n                xmlns=\"http://www.w3.org/2000/svg\"\n                width=\"14\"\n                height=\"14\"\n                viewBox=\"0 0 24 24\"\n                fill=\"none\"\n                stroke=\"currentColor\"\n                stroke-width=\"2\"\n                stroke-linecap=\"round\"\n                stroke-linejoin=\"round\"\n                aria-hidden=\"true\"\n              >\n                <polyline points=\"3 6 5 6 21 6\" />\n                <path d=\"M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6\" />\n                <path d=\"M10 11v6\" />\n                <path d=\"M14 11v6\" />\n                <path d=\"M9 6V4a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2\" />\n              </svg>\n            </button>\n            <svg\n              xmlns=\"http://www.w3.org/2000/svg\"\n              width=\"14\"\n              height=\"14\"\n              viewBox=\"0 0 24 24\"\n              fill=\"none\"\n              stroke=\"currentColor\"\n              stroke-width=\"2\"\n              stroke-linecap=\"round\"\n              stroke-linejoin=\"round\"\n              class=\"iz-row__chevron\"\n              :class=\"{ 'iz-row__chevron--open': expanded[member.userId] }\"\n            >\n              <polyline points=\"6 9 12 15 18 9\" />\n            </svg>\n          </div>\n        </div>\n\n        <!-- Expanded Detail -->\n        <div v-if=\"expanded[member.userId]\" class=\"iz-row__detail members-panel__detail\">\n          <div class=\"members-panel__detail-grid\">\n            <div class=\"members-panel__detail-item\" v-if=\"member.userId\">\n              <span class=\"members-panel__detail-label\">Username</span>\n              <span class=\"members-panel__detail-value\">{{\n                member.userId\n              }}</span>\n            </div>\n            <div class=\"members-panel__detail-item\" v-if=\"member.email\">\n              <span class=\"members-panel__detail-label\">Email</span>\n              <span class=\"members-panel__detail-value\">{{\n                member.email\n              }}</span>\n            </div>\n            <div class=\"members-panel__detail-item\" v-if=\"member.phone\">\n              <span class=\"members-panel__detail-label\">Phone</span>\n              <span class=\"members-panel__detail-value\">{{\n                member.phone\n              }}</span>\n            </div>\n            <div class=\"members-panel__detail-item\" v-if=\"member.organisation\">\n              <span class=\"members-panel__detail-label\">Organisation</span>\n              <span class=\"members-panel__detail-value\">{{\n                member.organisation\n              }}</span>\n            </div>\n            <div class=\"members-panel__detail-item\" v-if=\"member.title\">\n              <span class=\"members-panel__detail-label\">Title / Role</span>\n              <span class=\"members-panel__detail-value\">{{\n                member.title\n              }}</span>\n            </div>\n            <div class=\"members-panel__detail-item\">\n              <span class=\"members-panel__detail-label\">Org Role</span>\n              <span\n                class=\"members-panel__detail-value\"\n                style=\"text-transform: capitalize\"\n                >{{ member.role }}</span\n              >\n            </div>\n            <div class=\"members-panel__detail-item\" v-if=\"member.joinedAt\">\n              <span class=\"members-panel__detail-label\">Joined</span>\n              <span class=\"members-panel__detail-value\">{{\n                formatDate(member.joinedAt)\n              }}</span>\n            </div>\n            <div class=\"members-panel__detail-item\" v-if=\"member.lastActive\">\n              <span class=\"members-panel__detail-label\">Last Active</span>\n              <span class=\"members-panel__detail-value\">{{\n                formatDate(member.lastActive)\n              }}</span>\n            </div>\n          </div>\n\n          <!-- Task Stats Bar -->\n          <div v-if=\"member.assignedTasks > 0\" class=\"members-panel__tasks\">\n            <div class=\"members-panel__tasks-header\">\n              <span class=\"members-panel__tasks-title\">Task Performance</span>\n              <span class=\"members-panel__tasks-pct\"\n                >{{ taskPct(member) }}% complete</span\n              >\n            </div>\n            <div class=\"iz-meter members-panel__tasks-wrap\">\n              <div\n                class=\"iz-meter__fill\"\n                :style=\"{ width: taskPct(member) + '%' }\"\n                :class=\"taskFillClass(member)\"\n              ></div>\n            </div>\n            <div class=\"members-panel__tasks-legend\">\n              <span class=\"members-panel__tasks-stat\">\n                <span\n                  class=\"members-panel__dot members-panel__dot--done\"\n                ></span>\n                {{ member.doneTasks }} done\n              </span>\n              <span class=\"members-panel__tasks-stat\">\n                <span\n                  class=\"members-panel__dot members-panel__dot--open\"\n                ></span>\n                {{\n                  member.assignedTasks - member.doneTasks - member.overdueTasks\n                }}\n                in progress\n              </span>\n              <span\n                v-if=\"member.overdueTasks > 0\"\n                class=\"members-panel__tasks-stat\"\n              >\n                <span\n                  class=\"members-panel__dot members-panel__dot--overdue\"\n                ></span>\n                {{ member.overdueTasks }} overdue\n              </span>\n            </div>\n          </div>\n          <div v-else class=\"members-panel__tasks-empty\">\n            No task assignments yet\n          </div>\n        </div>\n      </div>\n\n      <!-- Pagination -->\n      <div v-if=\"totalPages > 1\" class=\"iz-pagination members-panel__pagination\">\n        <button\n          class=\"iz-btn iz-btn--icon members-panel__page-btn\"\n          :disabled=\"currentPage <= 1\"\n          @click=\"currentPage--\"\n        >\n          ‹\n        </button>\n        <span class=\"members-panel__page-info\">\n          {{ currentPage }} / {{ totalPages }}\n        </span>\n        <button\n          class=\"iz-btn iz-btn--icon members-panel__page-btn\"\n          :disabled=\"currentPage >= totalPages\"\n          @click=\"currentPage++\"\n        >\n          ›\n        </button>\n      </div>\n      <div\n        v-if=\"filteredMembers.length > 0\"\n        class=\"members-panel__showing-hint\"\n      >\n        Showing {{ paginatedMembers.length }} of\n        {{ filteredMembers.length }} members\n      </div>\n    </div>\n  </component>\n</template>\n\n<script>\nimport axios from \"@nextcloud/axios\";\nimport { generateOcsUrl } from \"@nextcloud/router\";\n\n// The organization app exposes its member endpoints under\n// /ocs/v2.php/apps/organization/... — OCS protocol, not plain app routes.\n// `@nextcloud/axios` injects requesttoken automatically, but OCS also needs\n// these headers on each call:\nconst OCS_HEADERS = {\n  \"OCS-APIRequest\": \"true\",\n  Accept: \"application/json\",\n};\n\nexport default {\n  name: \"MembersPanel\",\n  emits: [\"reload\"],\n  props: {\n    embedded: {\n      type: Boolean,\n      default: false,\n    },\n    members: {\n      type: Array,\n      default: function () {\n        return [];\n      },\n    },\n    orgId: {\n      type: Number,\n      required: true,\n    },\n    ownerUid: {\n      type: String,\n      default: null,\n    },\n  },\n  data: function () {\n    return {\n      collapsed: true,\n      expanded: {},\n      search: \"\",\n      roleFilter: \"\",\n      currentPage: 1,\n      pageSize: 5,\n      addMode: false,\n      addTab: \"existing\",\n      addSearchTerm: \"\",\n      addSearchResults: [],\n      addSearchLoading: false,\n      addError: null,\n      addingUid: null,\n      confirmRemoveUid: null,\n      removingUid: null,\n      removeError: null,\n      newUser: {\n        uid: \"\",\n        displayName: \"\",\n        email: \"\",\n        password: \"\",\n        autoGenerate: true,\n      },\n      newUserFieldErrors: {},\n      newUserBlurred: {},\n      newUserSubmitting: false,\n      newUserError: null,\n      newUserShowPassword: false,\n      createdUser: null,\n      revealCreatedPassword: false,\n      copyFlags: {},\n      toast: null,\n    };\n  },\n  created: function () {\n    this._addSearchDebounce = null;\n    this._addSearchToken = 0;\n    this._toastTimer = null;\n    this._copyTimers = {};\n  },\n  beforeDestroy: function () {\n    if (this._addSearchDebounce) clearTimeout(this._addSearchDebounce);\n    if (this._toastTimer) clearTimeout(this._toastTimer);\n    Object.keys(this._copyTimers || {}).forEach((k) => {\n      clearTimeout(this._copyTimers[k]);\n    });\n  },\n  computed: {\n    filteredMembers: function () {\n      var q = (this.search || \"\").toLowerCase();\n      var role = this.roleFilter;\n      var result = [];\n      for (var i = 0; i < this.members.length; i++) {\n        var m = this.members[i];\n        if (role && m.role !== role) {\n          continue;\n        }\n        if (q) {\n          var name = (m.displayName || \"\").toLowerCase();\n          var uid = (m.userId || \"\").toLowerCase();\n          var email = (m.email || \"\").toLowerCase();\n          if (\n            name.indexOf(q) === -1 &&\n            uid.indexOf(q) === -1 &&\n            email.indexOf(q) === -1\n          ) {\n            continue;\n          }\n        }\n        result.push(m);\n      }\n      return result;\n    },\n    totalPages: function () {\n      return Math.max(\n        1,\n        Math.ceil(this.filteredMembers.length / this.pageSize),\n      );\n    },\n    paginatedMembers: function () {\n      var start = (this.currentPage - 1) * this.pageSize;\n      return this.filteredMembers.slice(start, start + this.pageSize);\n    },\n    newUserFormValid: function () {\n      // Reactive validity check used to drive the submit-button disabled\n      // state. Mirrors validateNewUser() but without side effects so it can\n      // run on every keystroke.\n      var nu = this.newUser;\n      if (!nu.uid.trim()) return false;\n      if (!/^[A-Za-z0-9._@-]+$/.test(nu.uid.trim())) return false;\n      if (!nu.displayName.trim()) return false;\n      if (nu.email && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(nu.email.trim())) {\n        return false;\n      }\n      if (!nu.autoGenerate && nu.password.length < 10) return false;\n      if (!nu.password) return false;\n      return true;\n    },\n  },\n  watch: {\n    search: function () {\n      this.currentPage = 1;\n    },\n    filteredMembers: function () {\n      if (this.currentPage > this.totalPages) {\n        this.currentPage = this.totalPages;\n      }\n    },\n    addTab: function (val) {\n      // First time the New-user tab is opened (or after a successful submit\n      // reset cleared the password), seed a fresh auto-generated value.\n      if (val === \"new\" && this.newUser.autoGenerate && !this.newUser.password) {\n        this.newUser.password = this.generatePassword();\n      }\n    },\n  },\n  methods: {\n    toggle: function (uid) {\n      this.$set(this.expanded, uid, !this.expanded[uid]);\n    },\n    formatDate: function (dateStr) {\n      if (!dateStr) return \"—\";\n      var d = new Date(dateStr);\n      if (isNaN(d.getTime())) return dateStr;\n      return d.toLocaleDateString(\"en-GB\", {\n        day: \"2-digit\",\n        month: \"short\",\n        year: \"numeric\",\n      });\n    },\n    taskPct: function (m) {\n      if (!m.assignedTasks || m.assignedTasks === 0) return 0;\n      return Math.round((m.doneTasks / m.assignedTasks) * 100);\n    },\n    taskFillClass: function (m) {\n      var pct = this.taskPct(m);\n      if (pct >= 75) return \"iz-meter__fill--ok\";\n      if (pct >= 40) return \"iz-meter__fill--warn\";\n      return \"iz-meter__fill--danger\";\n    },\n    isOwner: function (member) {\n      return !!this.ownerUid && member && member.userId === this.ownerUid;\n    },\n    openAddMode: function () {\n      this.addMode = true;\n      this.addSearchTerm = \"\";\n      this.addSearchResults = [];\n      this.addError = null;\n      this.addingUid = null;\n      this.$nextTick(() => {\n        const el = this.$el.querySelector(\".members-panel__add-form-input\");\n        if (el && el.focus) el.focus();\n      });\n    },\n    closeAddMode: function () {\n      this.addMode = false;\n      if (this._addSearchDebounce) clearTimeout(this._addSearchDebounce);\n      this.addSearchTerm = \"\";\n      this.addSearchResults = [];\n      this.addSearchLoading = false;\n      this.addError = null;\n      this.addingUid = null;\n      this.addTab = \"existing\";\n      this.createdUser = null;\n      this.revealCreatedPassword = false;\n      this.resetNewUserForm();\n    },\n    onAddSearchInput: function (ev) {\n      this.addSearchTerm = ev.target.value;\n      if (this._addSearchDebounce) clearTimeout(this._addSearchDebounce);\n      if (this.addSearchTerm.trim().length < 2) {\n        this.addSearchResults = [];\n        this.addSearchLoading = false;\n        return;\n      }\n      this._addSearchDebounce = setTimeout(() => this.runAddSearch(), 300);\n    },\n    runAddSearch: async function () {\n      const term = this.addSearchTerm.trim();\n      if (term.length < 2) return;\n      const token = ++this._addSearchToken;\n      this.addSearchLoading = true;\n      this.addError = null;\n      try {\n        const res = await axios.get(\n          generateOcsUrl(\"/apps/organization/organizations/\" + this.orgId + \"/available-users\"),\n          {\n            params: { search: term, format: \"json\" },\n            headers: OCS_HEADERS,\n          }\n        );\n        if (token !== this._addSearchToken) return;\n        const data = (res.data && res.data.ocs && res.data.ocs.data) || res.data || {};\n        this.addSearchResults = data.users || [];\n      } catch (e) {\n        if (token !== this._addSearchToken) return;\n        const code = (e && e.response && e.response.status) || \"network\";\n        this.addError = \"Search failed (\" + code + \")\";\n        this.addSearchResults = [];\n      } finally {\n        if (token === this._addSearchToken) {\n          this.addSearchLoading = false;\n        }\n      }\n    },\n    addMember: async function (uid) {\n      if (this.addingUid !== null) return;\n      this.addingUid = uid;\n      this.addError = null;\n      try {\n        await axios.post(\n          generateOcsUrl(\"/apps/organization/organizations/\" + this.orgId + \"/members\"),\n          null,\n          {\n            params: { userId: uid, format: \"json\" },\n            headers: OCS_HEADERS,\n          }\n        );\n        this.closeAddMode();\n        this.$emit(\"reload\");\n      } catch (e) {\n        const code = (e && e.response && e.response.status) || \"network\";\n        this.addError = \"Failed to add (\" + code + \")\";\n      } finally {\n        this.addingUid = null;\n      }\n    },\n    requestRemove: function (uid) {\n      this.confirmRemoveUid = uid;\n      this.removeError = null;\n    },\n    cancelRemove: function () {\n      this.confirmRemoveUid = null;\n      this.removeError = null;\n    },\n    confirmRemove: async function (uid) {\n      if (this.removingUid !== null) return;\n      this.removingUid = uid;\n      this.removeError = null;\n      try {\n        await axios.delete(\n          generateOcsUrl(\n            \"/apps/organization/organizations/\" + this.orgId + \"/members/\" + encodeURIComponent(uid)\n          ),\n          {\n            params: { format: \"json\" },\n            headers: OCS_HEADERS,\n          }\n        );\n        this.confirmRemoveUid = null;\n        this.$emit(\"reload\");\n      } catch (e) {\n        const code = (e && e.response && e.response.status) || \"network\";\n        this.removeError = \"Failed to remove (\" + code + \")\";\n      } finally {\n        this.removingUid = null;\n      }\n    },\n    generatePassword: function () {\n      // 20 chars from a safe alphabet, sourced from window.crypto so values\n      // are unpredictable. crypto.getRandomValues is available in every\n      // browser this dashboard targets (Nextcloud requires it).\n      var alphabet =\n        \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*-_=+\";\n      var len = 20;\n      var out = \"\";\n      var arr = new Uint32Array(len);\n      window.crypto.getRandomValues(arr);\n      for (var i = 0; i < len; i++) {\n        out += alphabet.charAt(arr[i] % alphabet.length);\n      }\n      return out;\n    },\n    onAutoGenerateChange: function () {\n      // false → true: regenerate fresh.\n      // true → false: keep current value as an editable starting point.\n      if (this.newUser.autoGenerate) {\n        this.newUser.password = this.generatePassword();\n      }\n    },\n    markBlurred: function (field) {\n      this.$set(this.newUserBlurred, field, true);\n      this.validateNewUser();\n    },\n    validateNewUser: function () {\n      var errs = {};\n      var nu = this.newUser;\n      var uid = nu.uid.trim();\n      if (!uid) {\n        errs.uid = \"Required\";\n      } else if (!/^[A-Za-z0-9._@-]+$/.test(uid)) {\n        errs.uid = \"Use letters, digits, or . _ @ - (no spaces).\";\n      }\n      if (!nu.displayName.trim()) {\n        errs.displayName = \"Required\";\n      }\n      var email = nu.email.trim();\n      if (email && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)) {\n        errs.email = \"Invalid email address.\";\n      }\n      if (!nu.autoGenerate) {\n        if (!nu.password) {\n          errs.password = \"Required\";\n        } else if (nu.password.length < 10) {\n          errs.password = \"At least 10 characters.\";\n        }\n      }\n      this.newUserFieldErrors = errs;\n      return Object.keys(errs).length === 0;\n    },\n    submitNewUser: async function (